import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3]
    let it = xs.iterator().map(|x| x * 2)
    let jt = xs.iterator().map(|x| x * 2)
    let f = it.find(|x| x > 3)
    match f {
        Some(v) => { if v == 4 { io.println("find-ok") } else { io.println("find-bad") } }
        None => { io.println("find-none") }
    }

    let g = jt.find(|x| x > 9)
    match g {
        Some(v) => { io.println("find-miss-bad") }
        None => { io.println("find-miss-ok") }
    }

    return Ok(())
}
